 if(S.ws.schemaVersion<2){$('#work').innerHTML=`<div class="panel"><h2>將原本的故事接成三個章節</h2><p>原本的人物、情節、圖片與議事素材會保留在第一章，另外建立第二、三章的地圖。原本的公開版本維持不變。</p>${teacher()?'<button class="primary" data-act="migrate">保留原內容，轉成三章作品</button>':'<p>請等老師完成故事地圖安排。</p>'}</div>`;return}
