async function openCard(id,recover=false){if(!beforeLeave())return;await leave();let e=entity(id);if(!e||e.deleted)return;S.edit=cp(e);if(recover){let d=local.getItem(draftKey(id));if(d){S.edit.data=JSON.parse(d).data;S.edit.rev=JSON.parse(d).rev;S.dirty=true}}if(editable(e)){try{await api('lease',{entityId:id,clientId});S.lease=true}catch(err){notify(err.message)}}renderDrawer()}
