function renderDrawer(){let e=S.edit;if(!e)return;let d=e.data,can=editable(e)&&S.lease,disabled=!can,nodes=alive('node').filter(n=>n.data.chapterId===(e.type==='chapter'?e.id:d.chapterId)),body='',isTeacher=teacher();
 if(e.type==='info')body=field('完整作品名稱','title',d.title,false,disabled)+field('共同說明','intro',d.intro,true,disabled,'故事在哪裡、什麼時候發生？觀眾將扮演誰？為什麼需要做選擇？')+field('作品與歷史的說明','disclaimer',d.disclaimer,true,disabled);
 if(e.type==='role')body=field('人物姓名','name',d.name,false,disabled,'人物叫什麼名字？')+field('身分／職業','job',d.job,false,disabled,'他做什麼工作？在故事中有什麼身分？')+field('他的背景與生活經驗','background',d.background,true,disabled,'他住在哪裡？曾經歷什麼事？這些經驗如何影響他？')+field('他希望什麼？','want',d.want,false,disabled,'這個人物希望事情變成什麼樣子？')+field('他擔心什麼？','worry',d.worry,false,disabled,'他怕失去什麼？誰的處境會讓他猶豫？')+`<div class="section"><h3>人物關係</h3>${alive('relationship').filter(r=>r.data.from===e.id||r.data.to===e.id).map(r=>`<p><span class="tag">${esc(r.data.label)}</span> ${esc(title(entity(r.data.from===e.id?r.data.to:r.data.from)))}<br><small>${esc(r.data.description)}</small> <button type="button" class="small" data-act="open" data-id="${esc(r.id)}">查看關係卡</button></p>`).join('')||'<p class="muted">由教師先建立關係線，再派發關係卡編輯。</p>'}</div>`;
 if(e.type==='relationship')body=select('人物一','from',d.from,alive('role'),!isTeacher||disabled)+select('人物二','to',d.to,alive('role'),!isTeacher||disabled)+field('他們是什麼關係？','label',d.label,false,disabled)+field('他們會怎麼互相影響？','description',d.description,true,disabled);
 if(e.type==='chapter')body=field('章節名稱','title',d.title,false,disabled,'討論後再為這一章命名，可隨時修改。')+field('進入這一章時，觀眾讀到的引言','intro',d.intro,true,disabled,'交代這一章的時間、地點和新情況。人物遇到什麼難題？先讓觀眾了解處境，不必先說結果。')+(isTeacher?`<div class="section"><h3>章節安排</h3>${field('章節順序','order',d.order,false,disabled)}${field('一般路線至少經過幾幕？','minScenes',d.minScenes||3,false,disabled)}${field('至少有幾個結局？','minEndings',d.minEndings||3,false,disabled)}<h3 style="margin-top:20px">各角色從哪一幕開始？</h3>${alive('role').map(r=>`<label>${esc(r.data.name)}<select data-start="${esc(r.id)}" ${disabled?'disabled':''}><option value="">請指定起點</option>${nodes.filter(n=>n.data.kind!=='ending').map(n=>`<option value="${esc(n.id)}" ${d.starts?.[r.id]===n.id?'selected':''}>${esc(n.data.title)}</option>`).join('')}</select></label>`).join('')}</div>`:'');
 if(e.type==='node'){body=materialReferences(d,isTeacher)+(isTeacher?select('卡片類型','kind',d.kind,[{id:'choice',label:'選擇：觀眾做決定'},{id:'scene',label:'情節：接續發生的事'},{id:'ending',label:'本章結局'}],disabled):`<span class="tag ${d.kind}">${kind(d.kind)}</span>`)+field(d.kind==='ending'?'這個結局叫什麼？':'這一幕叫什麼？','title',d.title,false,disabled)+field(d.kind==='ending'?'哪些人的生活改變了？留下什麼影響？':'眼前發生什麼事？人物說了什麼？','text',d.text,true,disabled,d.kind==='ending'?'寫出前面的選擇造成什麼改變、影響了誰。這個結果可以留下什麼問題？':'交代時間、地點、發生的事，以及人物的反應。觀眾接下來需要決定什麼？')+`<label>這一幕涉及哪些人物？</label><div class="checkbox-list">${alive('role').map(r=>`<label><input type="checkbox" data-role="${esc(r.id)}" ${(d.roleIds||[]).includes(r.id)?'checked':''} ${disabled?'disabled':''}>${esc(r.data.name)}</label>`).join('')}</div>`;
  if(d.kind==='choice')body+=`<div class="section"><h3>觀眾可以怎麼做？選了之後呢？</h3>${(d.options||[]).map((o,i)=>`<div class="option-card" data-option="${esc(o.id)}" data-target="${esc(o.target)}" data-early="${!!o.early}"><b>選項 ${i+1}</b><label>可以採取的行動<input data-opt="label" placeholder="人物可以採取什麼行動？" value="${esc(o.label)}" ${disabled?'disabled':''}></label><label>選了之後，發生的結果<textarea data-opt="result" placeholder="這個行動會影響誰？接著會發生什麼事？" ${disabled?'disabled':''}>${esc(o.result)}</textarea></label>${isTeacher?`<label>接往哪一幕或結局？<select data-opt="target" ${disabled?'disabled':''}><option value="">暫時留白，稍後接線</option>${nodes.map(n=>`<option value="${esc(n.id)}" ${o.target===n.id?'selected':''}>${esc(n.data.title)}</option>`).join('')}</select></label><label style="font-size:14px;font-weight:400"><input type="checkbox" data-opt="early" ${o.early?'checked':''} ${disabled?'disabled':''}>這條線可以提前進入結局</label><button type="button" class="small danger" data-act="removeOption" data-id="${i}" ${disabled?'disabled':''}>移除選項</button>`:`<p class="muted">${o.target?'接往：'+esc(title(entity(o.target))):'等待老師接線'}${o.early?' · 提前結局':''}</p>`}</div>`).join('')}<button type="button" data-act="addOption" ${(d.options||[]).length>=4||disabled?'disabled':''}>＋ 增加選項與結果</button></div>`;
  if(d.kind==='scene'&&isTeacher)body+=select('接往下一幕','next',d.next,nodes,disabled)+`<label style="font-weight:400;font-size:14px"><input type="checkbox" data-field="nextEarly" ${d.nextEarly?'checked':''} ${disabled?'disabled':''}>允許這條線提前進入結局</label>`;
  if(d.kind==='ending')body+='<div class="notice good">這是本章的其中一種結果。玩家會保留這個結局，再以同一個身分進入下一章。</div>';
  body+=field('補充對話或反應（可留白）','response',d.response,true,disabled);
 }
 let image=['info','role','chapter','node'].includes(e.type)?imageBlock(d):'',sources=['info','role','chapter','node'].includes(e.type)?sourcesMarkup(d):'';
 $('#drawer-root').innerHTML=`<div class="drawer-wrap"><aside class="drawer" aria-label="卡片編輯"><header class="drawer-head row between"><div><small style="color:#cfddd1">${({info:'完整作品',role:'人物設定',relationship:'人物關係',chapter:'章節引言',node:kind(d.kind)})[e.type]} · 版本 ${e.rev}</small><h2>${esc(title(e))}</h2></div><button class="small" data-act="closeDrawer">返回地圖</button></header><div class="drawer-body">${!editable(e)?'<div class="notice">這張卡可以閱讀。編輯工作由老師分派。</div>':!S.lease?'<div class="notice">有人正在編輯，或編輯時間已到。<button class="small" data-act="reacquire">重新取得編輯權</button></div>':''}<form id="card-form">${body}${image}${sources}${assignments(d)}<div class="savebar row"><button type="submit" class="primary" id="save-button" data-act="saveCard" ${disabled||S.saving?'disabled':''}>${S.saving?'<span class="spinner"></span>儲存中':'儲存這張卡'}</button><span class="muted" id="save-status">${S.dirty?'尚未存到作品 · 本機草稿已保留':'已載入作品內容'}</span><button type="button" class="small" data-act="history">修改紀錄</button>${isTeacher&&!['info','layout'].includes(e.type)?'<button type="button" class="small danger" data-act="delete">移到回收區</button>':''}</div></form><div class="section"><h3>給這張卡的建議</h3>${alive('comment').filter(c=>c.data.targetId===e.id).map(c=>`<p><span class="tag">${esc(S.ws.users.find(u=>u.id===c.updatedBy)?.name||'作者')}</span> ${esc(c.data.text)}</p>`).join('')}<label>留言<textarea id="comment-text"></textarea></label><button data-act="comment">留下建議</button></div></div></aside></div>`;hydrate()}
function sourcesMarkup(d){let linked=(d.sourceIds||[]).map(entity).filter(e=>e&&!e.deleted);return `<div class="section"><h3>真實對照卡</h3><p class="muted">把史料與創作放在一起比較，不用離開這一幕。</p>${linked.map(s=>`<div class="source-card"><span class="tag source">${s.data.approved?'教師已核對':'待核對'}</span><h3 style="margin:10px 0">${esc(s.data.title||'尚未命名的對照卡')}</h3><p><b>史料：</b>${esc(s.data.fact)}</p><p><b>我們的故事：</b>${esc(s.data.fiction)}</p>${s.data.imageId?`<img class="preview-image" data-image="${esc(s.data.imageId)}" alt="對照圖片">`:''}${editable(S.edit)?`<button type="button" class="small" data-act="editSource" data-id="${esc(s.id)}">${editable(s)?'編輯':'查看'}對照卡</button><button type="button" class="small" data-act="unlinkSource" data-id="${esc(s.id)}">從本卡移除</button>`:''}</div>`).join('')}${editable(S.edit)?'<div class="toolbar"><button type="button" data-act="newSource">＋ 在這裡新增對照卡</button><button type="button" data-act="chooseSource">選用已有的對照卡</button></div>':''}<div id="source-editor">${S.source?sourceEditor():''}</div></div>`}
function sourceEditor(){let e=S.source,d=e.data,can=editable(e);return `<div class="source-card"><h3>編輯真實對照卡</h3>${['title','fact','fiction','url'].map((k,i)=>`<label>${['資料名稱','歷史資料提到什麼？','我們的故事怎麼運用或改寫？','原始資料網址'][i]}${i===1||i===2?`<textarea data-source-field="${k}" ${can?'':'disabled'}>${esc(d[k])}</textarea>`:`<input data-source-field="${k}" value="${esc(d[k])}" ${can?'':'disabled'}>`}</label>`).join('')}${teacher()?`<label style="font-weight:400"><input type="checkbox" data-source-field="approved" ${d.approved?'checked':''}>我已核對原始資料，確認史實可使用。</label>`:'<p class="muted">修改後，這張卡會重新等待老師核對。</p>'}${imageBlock(d,true)}${teacher()?`<label>這張對照卡由誰編輯？</label><div class="checkbox-list">${S.ws.users.filter(u=>u.role==='student'&&S.ws.project.members.includes(u.id)).map(u=>`<label><input type="checkbox" data-source-author="${esc(u.id)}" ${(d.assignees||[]).includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</div>`:''}<button type="button" class="primary" data-act="saveSource" ${can?'':'disabled'}>儲存對照卡</button><button type="button" data-act="closeSource">收起</button></div>`}
function readSource(){if(!S.source)return;$$('[data-source-field]').forEach(el=>S.source.data[el.dataset.sourceField]=el.type==='checkbox'?el.checked:el.value);if(teacher())S.source.data.assignees=$$('[data-source-author]:checked').map(x=>x.dataset.sourceAuthor);try{local.setItem(draftKey(S.source.id),JSON.stringify(S.source))}catch(_){}}
async function persistSource(){let e=S.source;if(!e||!editable(e))return;try{let current=entity(e.id);if(current&&JSON.stringify(current.data)===JSON.stringify(e.data)){local.removeItem(draftKey(e.id));S.source=cp(current);return current}let r=await api('save',{id:e.id,type:'source',data:e.data,expectedRev:e.rev,clientId});local.removeItem(draftKey(e.id));S.source=cp(r);let i=S.ws.entities.findIndex(x=>x.id===r.id);if(i>=0)S.ws.entities[i]=r;return r}catch(error){error.forSource=true;throw error}}
async function saveCard(){if(S.uploading){notify('圖片上傳中，請稍等完成後再儲存。');return}if(S.saving||!S.edit||!S.lease)return;readForm();readSource();S.saving=true;$('#card-form')?.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=true);let b=$('#save-button');if(b)b.innerHTML='<span class="spinner"></span>儲存中';try{if(S.source&&editable(S.source))await persistSource();let e=S.edit,r=await api('save',{id:e.id,type:e.type,data:e.data,expectedRev:e.rev,clientId});S.edit=r;S.dirty=false;local.removeItem(draftKey(e.id));await workspace();notify('已儲存到完整作品。')}catch(err){keepDraft();if(err.code==='CONFLICT'&&err.forSource)modal('<h3>對照卡已有新版本</h3><p>主卡片與對照卡草稿都已保留。請先比較新資料，再重新編寫。</p><pre class="history-text">'+esc(JSON.stringify(err.latest?.data||{},null,2))+'</pre><button data-act="latestSource">載入最新對照卡</button>');else if(err.code==='CONFLICT')conflict(err);else{if(err.code==='LEASE_EXPIRED')S.lease=false;fail(err)}}finally{S.saving=false;render()}}
function conflict(err){modal(`<div class="notice error">${esc(err.message)}</div><h3>作品中的新版本</h3><pre class="history-text">${esc(JSON.stringify(err.latest?.data||{},null,2))}</pre><h3>你的草稿</h3><pre class="history-text">${esc(JSON.stringify(S.edit?.data||{},null,2))}</pre><p>草稿仍在本機。先比較內容，再載入新版本，把要保留的句子補回去。</p><button data-act="loadLatest" class="primary">載入最新版本</button>`)}
async function create(type,data){if(!beforeLeave())return;await leave();let id='e-'+uid();if(type==='node')await api('lease',{entityId:id,clientId});let r=await api('save',{id,type,data,expectedRev:0,clientId});await workspace();await openCard(r.id);renderMap()}
async function saveLayout(id,pos){if(S.structureBusy)return;S.structureBusy=true;try{let layout=alive('layout')[0],d=cp(layout?.data||{positions:{}});d.positions[id]=pos;await api('save',{id:layout?.id||'layout',type:'layout',data:d,expectedRev:layout?.rev||0,clientId});await workspace()}catch(e){fail(e);await workspace()}finally{S.structureBusy=false;renderMap()}}
let drag=null;
document.addEventListener('pointerdown',e=>{let grab=e.target.closest('[data-grab]'),pin=e.target.closest('[data-pin]');if(!teacher()||!S.planning||S.structureBusy||(!grab&&!pin))return;e.preventDefault();let node=(grab||pin).closest('[data-node]'),rect=$('#map').getBoundingClientRect();drag={mode:pin?'link':'move',id:node.dataset.node,option:pin?.dataset.option,element:node,startX:e.clientX,startY:e.clientY,x:parseFloat(node.style.left),y:parseFloat(node.style.top),sourceX:e.clientX-rect.left,sourceY:e.clientY-rect.top};if(grab)node.classList.add('dragging')});
document.addEventListener('pointermove',e=>{if(!drag)return;e.preventDefault();if(drag.mode==='move'){drag.element.style.left=Math.max(0,drag.x+e.clientX-drag.startX)+'px';drag.element.style.top=Math.max(0,drag.y+e.clientY-drag.startY)+'px';drawEdges()}else{let rect=$('#map').getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;$('#drag-edge')?.setAttribute('d',`M${drag.sourceX} ${drag.sourceY} Q${drag.sourceX+70} ${y} ${x} ${y}`);$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));let target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]');if(target)target.classList.add('drop-target')}},{passive:false});
document.addEventListener('pointerup',async e=>{if(!drag)return;let d=drag;drag=null;$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));d.element.classList.remove('dragging');if(d.mode==='move'){await saveLayout(d.id,{x:parseFloat(d.element.style.left),y:parseFloat(d.element.style.top)});return}$('#drag-edge')?.setAttribute('d','');let target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]');if(!target)return;try{S.structureBusy=true;await api('connect',{id:d.id,optionId:d.option,target:target.dataset.node,early:false,expectedRev:entity(d.id).rev,clientId});await workspace();renderMap();notify('故事線已接好。若要提前到結局，請在卡片內勾選。')}catch(err){fail(err)}finally{S.structureBusy=false}});
document.addEventListener('pointercancel',()=>{drag=null;renderMap()});
async function imageUrl(id){let key=(S.player&&!S.player.preview?S.player.data.releaseId:'private')+':'+id;if(!S.images[key])S.images[key]=(S.player&&!S.player.preview?rpc('studioPublicImage',[S.player.data.projectId,S.player.data.releaseId,id]):api('image',{assetId:id})).catch(e=>{delete S.images[key];throw e});return S.images[key]}
async function hydrate(){let imgs=$$('[data-image]');let i=0;await Promise.allSettled(Array.from({length:Math.min(5,imgs.length)},async()=>{while(i<imgs.length){let img=imgs[i++];try{let u=await imageUrl(img.dataset.image);if(img.isConnected)img.src=u}catch(_){img.alt='圖片暫時無法讀取'}}}))}
function compress(file){return new Promise((resolve,reject)=>{let url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{let canvas=document.createElement('canvas'),ratio=Math.min(1,1400/Math.max(im.width,im.height));canvas.width=Math.round(im.width*ratio);canvas.height=Math.round(im.height*ratio);let cx=canvas.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,canvas.width,canvas.height);cx.drawImage(im,0,0,canvas.width,canvas.height);let q=.85,u=canvas.toDataURL('image/jpeg',q);while(u.length>990000&&q>.35){q-=.1;u=canvas.toDataURL('image/jpeg',q)}if(u.length>1000000)throw Error('圖片細節較多，請換成較小的圖片。');resolve(u)}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('無法讀取這張圖片。'))};im.src=url})}
async function upload(file,where){if(!file)return;if(S.uploading){notify('請先等上一張圖片上傳完成。');return}readForm();readSource();let e=where==='source'?S.source:S.edit,status=$('#upload-'+where),input=$(`[data-upload="${where}"]`);if(!e||!editable(e))return;S.uploading=true;input.disabled=true;if($('#save-button'))$('#save-button').disabled=true;status.textContent='正在縮小並上傳圖片……';try{if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw Error('請選 JPG、PNG 或 WebP 圖片。');if(file.size>15000000)throw Error('原圖請小於 15MB。');let u=await compress(file),asset=await api('upload',{entityId:e.id,name:file.name,dataUrl:u});S.ws.entities.push(asset);S.images['private:'+asset.id]=Promise.resolve(u);e.data.imageId=asset.id;if(where==='main'){S.dirty=true;keepDraft()}else readSource();renderDrawer();notify('圖片已上傳。請再儲存這張卡，讓圖片與內容一起留下。')}catch(err){fail(err);if(status.isConnected)status.textContent=err.message}finally{S.uploading=false;if(input.isConnected)input.disabled=false;if($('#save-button'))$('#save-button').disabled=!editable(S.edit)||!S.lease||S.saving}}
function showRelations(){let roles=alive('role'),pos={};roles.forEach((r,i)=>pos[r.id]={x:20+i%2*330,y:20+Math.floor(i/2)*155});let height=Math.max(180,Math.ceil(roles.length/2)*155+20),lines=alive('relationship').map(r=>{let a=pos[r.data.from],b=pos[r.data.to];if(!a||!b)return '';return `<line x1="${a.x+130}" y1="${a.y+45}" x2="${b.x+130}" y2="${b.y+45}" stroke="#89a58e" stroke-width="2"/>`}).join('');modal(`<h3>共同人物與關係</h3><div style="overflow:auto"><div style="position:relative;width:640px;height:${height}px;background:#f1f5ed;border-radius:12px"><svg width="640" height="${height}" style="position:absolute;inset:0" aria-hidden="true">${lines}</svg>${roles.map(r=>`<button data-act="openFromModal" data-id="${esc(r.id)}" style="position:absolute;left:${pos[r.id].x}px;top:${pos[r.id].y}px;width:260px;min-height:90px;text-align:left"><b>${esc(r.data.name)}</b><br><small>${esc(r.data.job)}</small></button>`).join('')}</div></div><h3 style="margin-top:20px">他們如何互相影響？</h3>${alive('relationship').map(r=>`<div class="panel"><div class="row"><b>${esc(title(entity(r.data.from)))}</b><span class="tag">${esc(r.data.label)}</span><b>${esc(title(entity(r.data.to)))}</b></div><p style="margin:10px 0">${esc(r.data.description)}</p><button data-act="openFromModal" data-id="${esc(r.id)}">${editable(r)?'編輯':'查看'}關係卡</button></div>`).join('')||'<p>還沒有關係卡。</p>'}${teacher()?'<button data-act="newRelation" class="primary">＋ 建立人物關係</button>':''}`)}
function playerLink(){return location.href.split('?')[0].split('#')[0]+'?play='+encodeURIComponent(S.pid)}
function materialIds(d){return [...new Set([...(d.originMaterialIds||[]),...(d.originMaterialId?[d.originMaterialId]:[])])]}
function materialReferences(d,isTeacher){let refs=materialIds(d).map(entity).filter(m=>m&&!m.deleted);return `<div class="section"><h3>議事庭參考素材</h3><p class="muted">從討論中挑選想延伸的部分，再自己寫成這一幕。原回合只供查找，可自由安排故事順序。</p>${refs.map(m=>`<details class="source-card"><summary>${esc(m.data.who)} · ${esc(m.data.action||'討論紀錄')}</summary><p><b>原議事庭回合：</b>${esc(m.data.stage)}</p><p><b>當時的決定：</b>${esc(m.data.action)}</p><p><b>理由：</b>${esc(m.data.reason)}</p><p><b>預想影響：</b>${esc(m.data.prediction)}</p>${m.data.setting?`<p><b>角色補充：</b>${esc(m.data.setting)}</p>`:''}${isTeacher?`<button type="button" class="small" data-act="removeMaterial" data-id="${esc(m.id)}">移除這一幕的參考</button>`:''}</details>`).join('')||'<p class="muted">尚未選用素材，可先與同學討論。</p>'}${isTeacher?'<button type="button" data-act="selectMaterialsForNode">選擇參考素材</button>':''}</div>`}
function materialNodeOptions(chapterId,nodeId=''){return '<option value="">請選擇幕次或結局</option>'+alive('node').filter(n=>n.data.chapterId===chapterId).map(n=>`<option value="${esc(n.id)}" ${n.id===nodeId?'selected':''}>${esc(kind(n.data.kind))} · ${esc(title(n))}</option>`).join('')}
function updateMaterialNodes(chapterId){$('#material-node').innerHTML=materialNodeOptions(chapterId)}
function showMaterials(selected=[],chapterId=S.chapter,nodeId=''){let chs=StoryModel.chapters(alive());modal(`<h3>議事庭素材：先挑紀錄，再安排位置</h3><div class="panel">${demo?'<p>此處只讀取虛構體驗紀錄，不會連接班級試算表。</p>':'<label>議事庭試算表 ID<input id="import-id" placeholder="貼上原議事庭試算表的 ID"></label>'}<button data-act="import">${demo?'讀取虛構體驗紀錄':'讀取議事庭紀錄'}</button><p class="muted">只讀取原本的 Events 紀錄，以作者代號顯示。讀取後先存為素材，不會自動命名章節、增加幕次或填入選項。</p></div><h3>1. 勾選要參考的討論</h3>${alive('material').map(m=>{let uses=alive('node').filter(n=>materialIds(n.data).includes(m.id));return `<div class="panel"><label style="font-weight:500"><input type="checkbox" data-material-select="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}>${esc(m.data.who)} · ${esc(m.data.action||'討論紀錄')}</label><small>原議事庭回合（僅供查找）：${esc(m.data.stage)}</small><p>理由：${esc(m.data.reason)}</p><p>預想影響：${esc(m.data.prediction)}</p>${m.data.setting?`<p>角色補充：${esc(m.data.setting)}</p>`:''}<p class="muted">${uses.length?'已參考於：'+uses.map(n=>esc(title(entity(n.data.chapterId)))+'／'+esc(title(n))).join('、'):'還沒安排到故事裡'}</p></div>`}).join('')||'<p class="muted">尚未讀取議事素材。</p>'}<div class="panel"><h3>2. 選擇放入哪裡</h3><label>章節<select id="material-chapter">${chs.map(ch=>`<option value="${esc(ch.id)}" ${ch.id===chapterId?'selected':''}>${esc(ch.data.title)}</option>`).join('')}</select></label><label>幕次或結局<select id="material-node">${materialNodeOptions(chapterId,nodeId)}</select></label><p class="muted">只加入參考區。名稱、劇情、選項與故事線由你們討論後修改。同一份素材也能放到不同幕次，延伸不同的故事。</p><button data-act="placeMaterials" class="primary" ${alive('material').length?'':'disabled'}>加入這一幕的參考素材</button></div>`)}
function showTeacher(){let check=StoryModel.validate(alive());modal(`<h3>完整作品的安排與發布</h3><div class="toolbar"><button data-act="members">安排共編成員</button><button data-act="recycle">回收區</button><button data-act="materials">議事庭素材</button><button data-act="prepareBlankWork">開啟三章空白作品</button></div><div class="panel"><h3>故事檢查</h3>${check.errors.length?`<div class="notice error">${esc(check.errors.join('\n'))}</div>`:'<div class="notice good">各章起點、故事線、幕數、結局與史料已通過檢查。</div>'}${check.warnings.map(w=>`<p class="muted">${esc(w)}</p>`).join('')}<button class="primary" data-act="publish">發布整份作品</button>${S.ws.project.releaseId?'<button data-act="unpublish">停止公開</button>':''}</div>${S.ws.project.releaseId?`<label>玩家網址<input readonly value="${esc(playerLink())}"></label>`:''}<p class="muted">發布後固定保留這一版。修改草稿不會立刻改動玩家正在看的故事。</p>`)}
async function showHistory(id){let e=entity(id),h=await api('history',{entityId:id});modal(`<h3>${esc(title(e))} · 修改紀錄</h3>${h.map(v=>`<details><summary>版本 ${v.rev} · ${esc(v.at.slice(0,19).replace('T',' '))} UTC · ${v.deleted?'移到回收區':'儲存'}</summary><pre class="history-text">${esc(JSON.stringify(v.data,null,2))}</pre>${teacher()?`<button data-act="restore" data-id="${esc(id)}" data-version="${esc(v.id)}">還原為新版本</button>`:''}</details>`).join('')}`)}
async function poll(){if(!S.user||!S.pid||S.saving||S.polling||S.structureBusy||document.hidden||S.player)return;S.polling=true;try{let old=S.edit,w=await api('workspace');S.ws=w;S.ws.entities=S.ws.entities.map(StoryModel.stripTemplate);if(old){let now=entity(old.id);if(now&&now.rev!==old.rev){if(!S.dirty&&!S.source){S.edit=now.deleted?null:cp(now);render()}else if($('#save-status'))$('#save-status').textContent='這張卡有新版本；草稿已保留，儲存時會先比較。'}}else render()}catch(_){if($('#save-status'))$('#save-status').textContent='連線暫時中斷，草稿仍保留。'}finally{S.polling=false}}
setInterval(poll,12000);setInterval(async()=>{if(S.edit&&S.lease&&!S.saving&&!document.hidden)try{await api('lease',{entityId:S.edit.id,clientId})}catch(e){S.lease=false;renderDrawer();fail(e)}},25000);
window.addEventListener('beforeunload',e=>{if(S.dirty){keepDraft();e.preventDefault();e.returnValue=''}});
document.addEventListener('input',e=>{if(e.target.closest('#card-form')&&!e.target.matches('[data-source-field]'))readForm();if(e.target.matches('[data-source-field]'))readSource()});
document.addEventListener('change',async e=>{try{if(e.target.id==='material-chapter'){updateMaterialNodes(e.target.value);return}if(e.target.matches('[data-upload]')){await upload(e.target.files[0],e.target.dataset.upload);return}if(e.target.matches('[data-field="kind"]')){readForm();renderDrawer()}if(e.target.id==='work-select'){if(!beforeLeave()){e.target.value=S.pid;return}await leave();S.pid=e.target.value;S.player=null;await workspace();render()}}catch(err){fail(err)}});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='login-form')await login($('#login-name').value,$('#login-pass').value);if(e.target.id==='card-form')await saveCard()});
document.addEventListener('click',async ev=>{let b=ev.target.closest('[data-act]');if(!b||S.saving)return;let a=b.dataset.act,id=b.dataset.id;if(S.uploading&&a!=='closeModal'){ev.preventDefault();notify('圖片上傳中，請稍等完成。');return}try{
 if(a==='saveCard'){ev.preventDefault();await saveCard();return}
 if(a==='closeModal')$('#modal').close();
 if(a==='demoLogin')await login(id,'demo');
 if(a==='logout'){if(!beforeLeave())return;await leave();S.player=null;S.ws=null;session.removeItem(TOKEN_KEY);loginScreen()}
 if(a==='chapter'){if(!beforeLeave())return;await leave();S.chapter=id;render()}
 if(a==='open')await openCard(id);
 if(a==='openFromModal'){$('#modal').close();await openCard(id)}
 if(a==='recover')await openCard(id,true);
 if(a==='closeDrawer'){if(beforeLeave()){await leave();render()}}
 if(a==='planning'){if(!beforeLeave())return;await leave();S.planning=!S.planning;render()}
 if(a==='reacquire'){let data=cp(S.edit);try{await api('lease',{entityId:data.id,clientId});S.lease=true;renderDrawer()}catch(e){fail(e)}}
 if(a==='migrate'){b.disabled=true;try{await api('migrate');await workspace();render();notify('已保留原內容並建立三章地圖。請教師先派發卡片。')}finally{b.disabled=false}}
 if(a==='newChapter'){let name=prompt('新增章節的名稱','新的章節');if(!name)return;b.disabled=true;try{let r=await api('addChapter',{title:name});await workspace();S.chapter=r.id;render()}finally{b.disabled=false}}
 if(a==='newRole')await create('role',{name:'新人物',job:'',background:'',want:'',worry:'',imageId:'',sourceIds:[],assignees:[]});
 if(a==='newRelation'){if($('#modal').open)$('#modal').close();let roles=alive('role');if(roles.length<2)throw Error('先建立兩位人物，再連結他們的關係。');await create('relationship',{from:roles[0].id,to:roles[1].id,label:'人物關係',description:'',assignees:[]})}
 if(a==='newNode'){let data={chapterId:S.chapter,kind:id,title:id==='ending'?'新的章節結局':'新的一幕',text:'',response:'',roleIds:[],sourceIds:[],assignees:[],imageId:'',options:id==='choice'?Array.from({length:3},()=>({id:'o-'+uid(),label:'',result:'',target:'',early:false})):[]};await create('node',data)}
 if(a==='addOption'){readForm();S.edit.data.options.push({id:'o-'+uid(),label:'',result:'',target:'',early:false});keepDraft();renderDrawer()}
 if(a==='removeOption'){readForm();S.edit.data.options.splice(Number(id),1);keepDraft();renderDrawer()}
 if(a==='clearImage'){if(!editable(id==='source'?S.source:S.edit))return;readForm();readSource();if(id==='source')S.source.data.imageId='';else S.edit.data.imageId='';keepDraft();renderDrawer()}
 if(a==='pickImage'){readForm();readSource();if(b.dataset.for==='source'){if(!editable(S.source))return;S.source.data.imageId=id}else{if(!editable(S.edit))return;S.edit.data.imageId=id;S.dirty=true;keepDraft()}renderDrawer()}
 if(a==='newSource'){readForm();let r=await api('save',{id:'source-'+uid(),type:'source',expectedRev:0,data:{title:'新的真實對照卡',fact:'',fiction:'',url:'',imageId:'',approved:false,ownerNodeId:S.edit.id,assignees:S.edit.data.assignees||[]},clientId});S.ws.entities.push(r);S.edit.data.sourceIds=S.edit.data.sourceIds||[];S.edit.data.sourceIds.push(r.id);S.source=cp(r);S.dirty=true;keepDraft();renderDrawer()}
 if(a==='editSource'){readForm();S.source=cp(entity(id));let d=local.getItem(draftKey(id));if(d&&editable(S.source)&&confirm('這張對照卡有本機草稿，要接回嗎？'))S.source=JSON.parse(d);renderDrawer()}
 if(a==='closeSource'){readSource();S.source=null;renderDrawer()}
 if(a==='saveSource'){readSource();b.disabled=true;try{let e=S.source,r=await api('save',{id:e.id,type:'source',data:e.data,expectedRev:e.rev,clientId});local.removeItem(draftKey(e.id));S.source=cp(r);let i=S.ws.entities.findIndex(x=>x.id===r.id);S.ws.entities[i]=r;renderDrawer();notify('對照卡已儲存。記得也儲存主卡片。')}catch(e){if(e.code==='CONFLICT')modal('<h3>對照卡已有新版本</h3><p>你的草稿保留在本機。請先收起並重新開啟對照卡，比較後再修改。</p><pre class="history-text">'+esc(JSON.stringify(e.latest?.data||{},null,2))+'</pre>');else throw e}finally{b.disabled=false}}
 if(a==='chooseSource'){readForm();modal(`<h3>選用已有的真實對照卡</h3>${alive('source').map(s=>`<p><button data-act="linkSource" data-id="${esc(s.id)}">${esc(s.data.title)}</button> <span class="tag source">${s.data.approved?'已核對':'待核對'}</span></p>`).join('')||'<p>還沒有對照卡，可以回到卡片直接新增。</p>'}`)}
 if(a==='unlinkSource'){readForm();S.edit.data.sourceIds=(S.edit.data.sourceIds||[]).filter(x=>x!==id);S.dirty=true;keepDraft();renderDrawer()}
 if(a==='linkSource'){S.edit.data.sourceIds=Array.from(new Set([...(S.edit.data.sourceIds||[]),id]));S.dirty=true;keepDraft();$('#modal').close();renderDrawer()}
 if(a==='relations')showRelations();
 if(a==='teacher')showTeacher();
 if(a==='history')await showHistory(id||S.edit.id);
 if(a==='latestSource'){let id=S.source.id;await workspace();S.source=cp(entity(id));$('#modal').close();renderDrawer()}
 if(a==='loadLatest'){let id=S.edit.id;$('#modal').close();S.dirty=false;await workspace();await openCard(id)}
 if(a==='delete'){if(!confirm(S.edit.type==='chapter'?'移除這章與章內卡片？所有卡片會進回收區，可由教師逐張還原。':'要將這張卡移到回收區嗎？'))return;let e=S.edit;await api('delete',{id:e.id,expectedRev:e.rev,clientId});local.removeItem(draftKey(e.id));await leave();await workspace();render()}
 if(a==='restore'){b.disabled=true;try{await api('restore',{id,expectedRev:entity(id).rev,versionId:b.dataset.version,clientId});$('#modal').close();if(S.edit?.id===id){S.dirty=false;await leave()}await workspace();render();notify('已還原為新版本。')}finally{b.disabled=false}}
 if(a==='recycle')modal(`<h3>回收區</h3><p class="muted">若移除了整章，先還原章節卡，再逐張還原需要的幕與結局。</p>${S.ws.entities.filter(e=>e.deleted).map(e=>`<p>${esc(title(e))} <button class="small" data-act="history" data-id="${esc(e.id)}">查看與還原</button></p>`).join('')||'<p>目前沒有移除的卡片。</p>'}`);
 if(a==='comment'){let text=$('#comment-text').value.trim();if(!text)return;readForm();b.disabled=true;try{await api('save',{id:'comment-'+uid(),type:'comment',data:{text,targetId:S.edit.id},expectedRev:0,clientId});await workspace();renderDrawer()}finally{b.disabled=false}}
 if(a==='assignChapter')modal(`<h3>派發「${esc(title(entity(S.chapter)))}」</h3><p>一起派發本章引言、所有幕與結局。之後仍可在單張卡片調整分工。</p>${S.ws.users.filter(u=>u.role==='student'&&S.ws.project.members.includes(u.id)).map(u=>`<label style="font-weight:400"><input type="checkbox" data-chapter-author="${esc(u.id)}">${esc(u.name)}</label>`).join('')}<button data-act="saveChapterAuthors" class="primary">派發本章的卡片</button>`);
 if(a==='saveChapterAuthors'){b.disabled=true;try{let affected=alive().filter(e=>e.id===S.chapter||e.type==='node'&&e.data.chapterId===S.chapter),revisions={};affected.forEach(e=>revisions[e.id]=e.rev);let r=await api('assignChapter',{chapterId:S.chapter,assignees:$$('[data-chapter-author]:checked').map(x=>x.dataset.chapterAuthor),revisions,clientId});$('#modal').close();await workspace();render();notify('已派發 '+r.count+' 張卡片。')}finally{b.disabled=false}}
 if(a==='members')modal(`<h3>完整作品的共編成員</h3>${S.ws.users.filter(u=>u.role==='student').map(u=>`<label style="font-weight:400"><input type="checkbox" data-member="${esc(u.id)}" ${S.ws.project.members.includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}<button data-act="saveMembers" class="primary">儲存成員</button>`);
 if(a==='saveMembers'){await api('members',{members:$$('[data-member]:checked').map(x=>x.dataset.member)});$('#modal').close();await workspace();render()}
 if(a==='publish'){b.disabled=true;b.innerHTML='<span class="spinner"></span>檢查與發布中';try{let rel=await api('publish');await workspace();$('#modal').close();render();modal(`<h3>整份作品已發布，第 ${rel.version} 版</h3><label>玩家網址<input readonly value="${esc(playerLink())}"></label><p>三個章節會一起固定保留在這個版本中。</p>`)}catch(e){modal('<h3>發布前，請先補上這些地方</h3><div class="notice error">'+esc(e.message)+'</div>')}finally{if(b.isConnected){b.disabled=false;b.textContent='發布整份作品'}}}
 if(a==='unpublish'&&confirm('要停止公開整份作品嗎？已儲存內容會保留。')){await api('unpublish');await workspace();render();showTeacher()}
 if(a==='materials')showMaterials();
 if(a==='import'){let source=demo?'demo':$('#import-id').value.trim();if(!source)throw Error('請填入議事庭試算表 ID。');b.disabled=true;b.innerHTML='<span class="spinner"></span>讀取中';try{let result=await api('importDecisions',{spreadsheetId:source});await workspace();showMaterials();notify('已讀取 '+result.count+' 份新素材。請勾選素材，再選擇放入的章節與幕次。')}finally{if(b.isConnected){b.disabled=false;b.textContent='讀取議事庭紀錄'}}}
 if(a==='fromMaterial')showMaterials([id]);
 if(a==='selectMaterialsForNode'){if(!beforeLeave())return;let n=cp(S.edit);await leave();showMaterials([],n.data.chapterId,n.id)}
 if(a==='placeMaterials'){let ids=$$('[data-material-select]:checked').map(x=>x.dataset.materialSelect),chapterId=$('#material-chapter').value,nodeId=$('#material-node').value;if(!ids.length)throw Error('請先勾選要使用的議事素材。');let n=entity(nodeId);if(!n||n.data.chapterId!==chapterId)throw Error('請選擇要放入的章節與幕次。');if(!S.ws.features?.materialPlacement)throw Error('請先更新 GAS 後台至本次提供的版本，再安排素材。');if(!beforeLeave())return;b.disabled=true;b.innerHTML='<span class="spinner"></span>加入參考素材中';try{await leave();await api('attachMaterials',{nodeId,chapterId,materialIds:ids,expectedRev:n.rev,clientId});await workspace();S.chapter=chapterId;$('#modal').close();render();await openCard(nodeId);notify('已加入這一幕的參考素材。名稱、劇情、選項與接線都保留。')}finally{if(b.isConnected){b.disabled=false;b.textContent='加入這一幕的參考素材'}}}
 if(a==='removeMaterial'){if(!teacher())return;readForm();S.edit.data.originMaterialIds=materialIds(S.edit.data).filter(x=>x!==id);S.edit.data.originMaterialId='';S.dirty=true;keepDraft();renderDrawer()}
 if(a==='prepareBlankWork'){if(!demo&&!S.ws.features?.blankWork)throw Error('請先更新 GAS 後台至本次提供的版本。');if(!beforeLeave())return;b.disabled=true;try{await leave();let p=await api('prepareBlankWork');S.projects=await api('listProjects');S.pid=p.id;S.chapter='';await workspace();$('#modal').close();render();notify(p.created?'已建立三章空白作品。':'已開啟共創作品；原有內容保留。')}finally{if(b.isConnected)b.disabled=false}}
 if(a==='preview'){if(!beforeLeave())return;await leave();startPlayer({schemaVersion:2,projectId:S.pid,version:'草稿',entities:StoryModel.publicEntities(alive())},true)}
 if(a==='backEditor'){S.player=null;render()}
 if(a==='chooseRole'){let p=S.player;p.role=id;p.chapter=0;p.view='intro';p.path=[];p.choices=[];p.endings=[];remember();renderPlayer()}
 if(a==='enterChapter'){let p=S.player,ch=StoryModel.chapters(p.data.entities)[p.chapter];p.path=[ch.data.starts?.[p.role]||''];p.view='node';p.result=null;remember();renderPlayer()}
 if(a==='chooseOption'){let p=S.player,node=p.data.entities.find(n=>n.id===p.path.at(-1)),o=node.data.options[Number(id)];p.result={label:o.label,text:o.result,target:o.target,at:p.path.length};p.choices.push({chapterId:node.data.chapterId,nodeId:node.id,title:node.data.title,label:o.label,result:o.result,at:p.path.length});p.view='result';remember();renderPlayer()}
 if(a==='continueResult'){let p=S.player;p.path.push(p.result.target);p.result=null;p.view='node';remember();renderPlayer()}
 if(a==='nextScene'){S.player.path.push(id);remember();renderPlayer()}
 if(a==='nextChapter'){let p=S.player;recordEnding();p.chapter++;p.path=[];p.view='intro';p.result=null;remember();renderPlayer()}
 if(a==='finish'){recordEnding();S.player.view='summary';remember();archiveRun();renderPlayer()}
 if(a==='restart'){if(S.player.view!=='summary'&&S.player.role&&!confirm('要結束這次體驗，重新選擇角色嗎？'))return;archiveRun();let data=S.player.data,preview=S.player.preview;startPlayer(data,preview,true)}
 if(a==='playBack'){let p=S.player;if(p.view==='result'){p.choices.pop();p.result=null;p.view='node'}else if(p.path.length>1){p.path.pop();p.choices=p.choices.filter(c=>c.chapterId!==StoryModel.chapters(p.data.entities)[p.chapter].id||c.at<p.path.length)}remember();renderPlayer()}
 }catch(err){fail(err)}});
function startPlayer(data,preview=false,fresh=false){data={...data,entities:StoryModel.adaptLegacy(data.entities)};S.player={data,preview,runId:uid(),startedAt:new Date().toISOString(),role:'',chapter:0,path:[],choices:[],endings:[],result:null,view:'start'};if(!preview&&!fresh){let saved=local.getItem('studio-v2-play:'+data.projectId+':'+data.releaseId);if(saved)try{let p=JSON.parse(saved);if(!p.role||data.entities.some(e=>e.id===p.role&&e.type==='role'))Object.assign(S.player,p,{data,preview:false})}catch(_){}}renderPlayer()}
function remember(){let p=S.player;if(!p.preview)try{let {data,preview,...save}=p;local.setItem('studio-v2-play:'+data.projectId+':'+data.releaseId,JSON.stringify(save))}catch(_){}}
function recordEnding(){let p=S.player,ch=StoryModel.chapters(p.data.entities)[p.chapter],node=p.data.entities.find(e=>e.id===p.path.at(-1));if(!node||node.data.kind!=='ending')return;p.endings=p.endings.filter(e=>e.chapterId!==ch.id);p.endings.push({chapterId:ch.id,chapterTitle:ch.data.title,title:node.data.title,text:node.data.text,nodeId:node.id})}
function archiveRun(){let p=S.player;if(p.preview||!p.role)return;try{let key='studio-v2-runs:'+p.data.projectId,runs=JSON.parse(local.getItem(key)||'[]'),record={runId:p.runId,role:p.role,releaseId:p.data.releaseId,startedAt:p.startedAt,finishedAt:p.view==='summary'?new Date().toISOString():null,choices:p.choices,endings:p.endings};runs=runs.filter(r=>r.runId!==p.runId);runs.push(record);local.setItem(key,JSON.stringify(runs.slice(-50)))}catch(_){}}
function sourceView(s){if(!s||!s.data.approved)return '';let d=s.data;return `<div class="source-card"><h3>${esc(d.title)}</h3><p><b>歷史資料：</b>${esc(d.fact)}</p><p><b>故事創作：</b>${esc(d.fiction||'角色的對話與選擇由學生創作。')}</p>${d.imageId?`<img class="play-image" data-image="${esc(d.imageId)}" alt="史料對照圖片">`:''}${/^https:\/\//i.test(d.url)?`<a target="_blank" rel="noopener" href="${esc(d.url)}">查看原始資料</a>`:''}</div>`}
function sourcesView(d,es){let sources=(d.sourceIds||[]).map(id=>es.find(e=>e.id===id)).filter(e=>e?.data.approved);return sources.length?'<details><summary>看看真實歷史</summary>'+sources.map(sourceView).join('')+'</details>':''}
function renderPlayer(){let p=S.player,es=p.data.entities,info=es.find(e=>e.type==='info')?.data||{},chs=StoryModel.chapters(es),ch=chs[p.chapter],role=es.find(e=>e.id===p.role),node=es.find(e=>e.id===p.path.at(-1)),body='',history=p.endings.map(e=>`<div class="ending-list"><span class="tag ending">${esc(e.chapterTitle)}</span><h3 style="margin:10px 0">${esc(e.title)}</h3><p>${esc(e.text)}</p></div>`).join('');$('#drawer-root').innerHTML='';
 if(p.view==='start')body=`<div class="hero"><div class="eyebrow">ONE ROLE · THREE CHAPTERS</div><h1>${esc(info.title||'糖的多重宇宙')}</h1>${info.imageId?`<img class="play-image" data-image="${esc(info.imageId)}" alt="作品圖片">`:''}<div style="white-space:pre-wrap">${esc(info.intro)}</div></div><h2 style="margin-top:28px">選一個身分，陪他走完整個故事</h2><div class="grid">${es.filter(e=>e.type==='role').map(r=>`<article class="card">${r.data.imageId?`<img class="play-image" data-image="${esc(r.data.imageId)}" alt="${esc(r.data.name)}">`:''}<span class="tag">${esc(r.data.job)}</span><h2 style="margin:12px 0">${esc(r.data.name)}</h2><p>${esc(r.data.background)}</p><p><b>期望：</b>${esc(r.data.want)}</p><p><b>擔心：</b>${esc(r.data.worry)}</p><button class="primary" data-act="chooseRole" data-id="${esc(r.id)}">以這個身分開始</button></article>`).join('')}</div><p class="muted" style="margin-top:25px">${esc(info.disclaimer)}</p>${sourcesView(info,es)}`;
 else if(p.view==='intro'&&ch)body=`<article class="play-card"><span class="tag">${esc(role?.data.name)} · 第 ${p.chapter+1} 章</span><h1 style="margin:18px 0">${esc(ch.data.title)}</h1>${ch.data.imageId?`<img class="play-image" data-image="${esc(ch.data.imageId)}" alt="章節圖片">`:''}<div class="story-text">${esc(ch.data.intro)}</div>${p.endings.length?'<details><summary>上一章發生的事</summary>'+history+'</details>':''}<button class="primary" data-act="enterChapter">進入這一章</button>${sourcesView(ch.data,es)}</article>`;
 else if(p.view==='summary')body=`<article class="play-card"><div class="eyebrow">YOUR COMPLETE STORY</div><h1>這一次，你成為了${esc(role?.data.name)}</h1><p>你用同一個身分走過了 ${chs.length} 個章節。這是你留下的故事。</p>${history}<details><summary>回看每一次選擇</summary>${p.choices.map(c=>`<p>在「${esc(c.title)}」選了：<b>${esc(c.label)}</b><br><small>${esc(c.result)}</small></p>`).join('')}</details><button class="primary" data-act="restart">換個角色，建立新的一次體驗</button><p class="muted" style="margin-top:18px">${p.preview?'作者試玩不會保存正式玩家紀錄。':'這次體驗已保留在此瀏覽器。重新開始會建立新的紀錄，不會蓋掉這一次。'}</p></article>`;
 else if(!node)body='<div class="notice error">這條故事線還沒接好。請老師回到地圖設定角色起點或下一幕。</div>';
 else if(p.view==='result')body=`<article class="play-card"><span class="tag">${esc(role?.data.name)}</span><h2 style="margin-top:16px">你選擇：${esc(p.result.label)}</h2><div class="result">${esc(p.result.text||'接著，故事有了變化。')}</div><button class="primary" data-act="continueResult">繼續看看發生什麼事</button><button data-act="playBack">重新想這次選擇</button></article>`;
 else {let d=node.data;body=`<article class="play-card"><div class="row between"><span class="tag">${esc(role?.data.name)} · ${esc(ch?.data.title)}</span><span class="tag ${d.kind}">${d.kind==='ending'?'本章的其中一個結局':'第 '+p.path.length+' 幕'}</span></div><h1 style="margin-top:20px">${esc(d.title)}</h1>${d.imageId?`<img class="play-image" data-image="${esc(d.imageId)}" alt="${esc(d.title)}">`:''}<div class="story-text">${esc(d.text)}</div>${d.response?'<p style="white-space:pre-wrap">'+esc(d.response)+'</p>':''}<div class="play-options">${d.kind==='choice'?(d.options||[]).map((o,i)=>`<button data-act="chooseOption" data-id="${i}">${esc(o.label||'尚未寫好的選項')}</button>`).join(''):d.kind==='scene'?`<button class="primary" data-act="nextScene" data-id="${esc(d.next)}">繼續故事</button>`:`<button class="primary" data-act="${p.chapter<chs.length-1?'nextChapter':'finish'}">${p.chapter<chs.length-1?'以同一個身分，進入下一章':'看完整的體驗紀錄'}</button>`}</div>${sourcesView(d,es)}</article>${p.path.length>1?'<div class="toolbar"><button data-act="playBack">回到本章上一幕</button></div>':''}`}
 $('#app').innerHTML=`<main class="play">${p.preview?'<div class="notice row between"><span>作者試玩 · 已儲存的草稿，不會公開。</span><button data-act="backEditor">回到故事地圖</button></div>':'<div class="row between" style="margin-bottom:20px"><div class="brand">糖的多重宇宙</div><small>完整作品 · 第 '+esc(p.data.version)+' 版</small></div>'}<div class="progress">${chs.map((c,i)=>`<span class="${i<=p.chapter&&p.role?'done':''}"></span>`).join('')}</div>${body}<details><summary>歷史資料與創作說明</summary><p class="muted">${esc(info.disclaimer)}</p>${es.filter(e=>e.type==='source'&&e.data.approved).map(sourceView).join('')||'<p class="muted">尚未加入教師確認的資料。</p>'}</details><p class="muted">本遊戲由 Peiching 製作。</p></main>`;hydrate();window.scrollTo({top:0,behavior:'smooth'})}
(async function boot(){let play=new URLSearchParams(location.search).get('play');if(play){try{startPlayer(await rpc('studioPublished',[play]),false)}catch(e){$('#app').innerHTML='<main class="play panel"><h1>故事暫時無法開啟</h1><p>'+esc(e.message)+'</p></main>'}return}if(!demo&&(!window.studioTransport||!window.studioTransport.isConfigured())){$('#app').innerHTML='<main class="login-wrap panel"><h1>故事創作室已就緒</h1><p>請老師先在 config.js 設定 GAS 的 /exec 連線網址。</p></main>';return}if(S.token){try{S.projects=await api('listProjects');S.pid=S.projects[0]?.id||'';if(S.pid){await workspace();let id=demo?S.token.split(':')[1]:JSON.parse(atob(S.token.split('.')[0].replace(/-/g,'+').replace(/_/g,'/'))).id;S.user=S.ws.users.find(u=>u.id===id);if(S.user){render();return}}}catch(_){}}loginScreen()})();
